function parseQuiz(text){
  text=(text||'').replace(/\r/g,'');
  var lines=text.split('\n'), out=[];
  for(var i=0;i<lines.length;i++){
    var ln=lines[i].trim(); if(!ln||ln[0]==='#') continue;
    var p=ln.split(/\s*\|\s*/);
    if(p.length>=3){
      var ans=parseInt(p[p.length-1],10);
      if(!isNaN(ans)) out.push({q:p[0], options:p.slice(1,p.length-1), answer:ans});
    }
  }
  return out;
}
function grade(quiz, answers){
  var correct=0;
  for(var i=0;i<quiz.length;i++){ if(answers[i]===quiz[i].answer) correct++; }
  return {correct:correct, total:quiz.length, pct: quiz.length? Math.round(correct/quiz.length*100):0};
}
function shuffle(arr, rng){ var a=arr.slice(); for(var i=a.length-1;i>0;i--){var j=Math.floor(rng()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;} return a; }
var EXPORTS={parseQuiz:parseQuiz, grade:grade, shuffle:shuffle};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.QuizForgePure = EXPORTS; }
